  (* [comment removed for export] *)
  Lemma seg_stack_apres : forall s' LB' m0 SP m m1 l h,
    as_RHEAP H s' LB' m0 -> munch [(l, h)]%Z m m1 -> wmono bsegs m m1 -> aceil <= l -> h <= SP -> apres H LB' SP m m1.
  Proof.
    intros s' LB' m0 SP m m1 l h HP MU WM CE HS. eapply (apres_of_munch H HH); [exact HP| exact MU| exact WM|].
    constructor; [cbn; lia| constructor].
  Qed.

